function run()
{
// tell ACME telemetry that the script is running
setScriptStateRunning();
// print parameters for a record of what was used after any changes
printParams();
var cirManifoldsOpen = false;
var ipsusStarted = false;
burnerOverLimitSecs = 0;
try
{
print("s-Flame test point " + parameters.testpointName + " STARTED");
// Check that MFCS are in operate state
if ( FlowTelemetry.MFCA2BypassState != 4) { print("WARNING: MFCA2 not in Operate state"); }
if ( FlowTelemetry.MFCA3FuelState != 4) { print("WARNING: MFCA3 not in Operate state"); }
// check that all of the flows are within the MFCs full scales. Throw exception if not.
if ( parameters.nitrogenIgnitionFlowRateN2Slpm > FlowTelemetry.MFCA2BypassFullScaleFlowSlpm
)
throw("INVALID PARAMETER: nitrogenIgnitionFlowRateN2Slpm exceeds MFCA2 maximum");
if ( parameters.nitrogenTestFlowRateN2Slpm > FlowTelemetry.MFCA2BypassFullScaleFlowSlpm )
throw("INVALID PARAMETER: nitrogenTestFlowRateN2Slpm exceeds MFCA2 maximum");
if ( parameters.fuelBottleIgnitionFlowRateN2Slpm > FlowTelemetry.MFCA3FuelFullScaleFlowSlpm )
throw("INVALID PARAMETER: fuelBottleIgnitionFlowRateN2Slpm exceeds MFCA3 maximum");
if ( parameters.fuelBottleTestFlowRateN2Slpm > FlowTelemetry.MFCA3FuelFullScaleFlowSlpm )
throw("INVALID PARAMETER: fuelBottleTestFlowRateN2Slpm exceeds MFCA3 maximum");
if ( ExtinctionDetectionTelemetry.extinctionDetectionAveragingDuration <= 0 )
throw ("Extinction detection averaging duration must be greater than zero.");
// check that these parameters are multiples of 50 which is required in the ignition sequence
// which loops every 50 msecs and uses exact msec timestamps
if ( parameters.fuelFlowIgnitionDeltaMs % 50 > 0)
throw("INVALID PARAMETER: fuelFlowIgnitionDeltaMs must be 0 or a multiple of 50");
if ( parameters.igniterPreheatTimeMs % 50 > 0)
throw("INVALID PARAMETER: igniterPreheatTimeMs must be 0 or a multiple of 50");
if ( parameters.igniterDelayBeforeRetractMs % 50 > 0)
throw("INVALID PARAMETER: igniterDelayBeforeRetractMs must be 0 or a multiple of 50");
if ( DiagnosticTelemetry.PMTPower < 4.0) { print("WARNING: PMT's are not powered."); }
print("Setting PMT gains");
PmtSetAllGains.PMT1Gain = parameters.pmt1Gain;
PmtSetAllGains.PMT2Gain = parameters.pmt2Gain;
PmtSetAllGains.PMT3Gain = parameters.pmt3Gain;
