sendCommand(PmtSetAllGains);
// Figure out and display the timing of ignition-related events
// times are milliseconds from the start of N2 priming, even if that is not performed
var fuelOpenValvesTimeMs = parameters.nitrogenPriming2DurationSec * 1000;
var fuelOpenMfcsTimeMs = fuelOpenValvesTimeMs + 500;
var igniterIgnitionTimeMs = fuelOpenValvesTimeMs + parameters.fuelFlowIgnitionDeltaMs;
var igniterPreheatTimeMs = igniterIgnitionTimeMs - parameters.igniterPreheatTimeMs;
var igniterRetractTimeMs = igniterIgnitionTimeMs + parameters.igniterDelayBeforeRetractMs;
var minTime = Math.min(fuelOpenValvesTimeMs, fuelOpenMfcsTimeMs, igniterIgnitionTimeMs,
igniterPreheatTimeMs, igniterRetractTimeMs );
if ( minTime < 0 )
{
// add to get every time above 0
fuelOpenValvesTimeMs += (-1 * minTime);
fuelOpenMfcsTimeMs += (-1 * minTime);
igniterIgnitionTimeMs += (-1 * minTime);
igniterPreheatTimeMs += (-1 * minTime);
igniterRetractTimeMs += (-1 * minTime);
}
var stabilizationTime1Ms = Math.max(igniterRetractTimeMs,fuelOpenValvesTimeMs);
print("Ignition Timing Values:");
print("----------------------");
if ( parameters.nitrogenIgnitionFlowRateN2Slpm > 0)
print("Start of N2 priming (period 2): 0 Ms");
print("Start of Fuel flow at ignition rate " + fuelOpenValvesTimeMs + " Ms");
if ( parameters.igniterPreheatTimeMs > 0 )
print("Start of igniter preheat: " + igniterPreheatTimeMs + " Ms");
print("Start of ignition: " + igniterIgnitionTimeMs + " Ms");
print("Start of igniter retraction: " + igniterRetractTimeMs + " Ms");
print("Start of stabilization time 1: " + stabilizationTime1Ms + " Ms");
print("----------------------");
var burnerTemperatureLimitV =
convertKTypeThermocoupleTempToVolts(parameters.burnerTemperatureLimitC,
DiagnosticTelemetry.tcCj);
print("temperature limit of " + parameters.burnerTemperatureLimitC + " C is " +
burnerTemperatureLimitV*1000 + "mV");
// Open the test point
if(parameters.testpointName == "NONE") { throw "Must define a test point name."; }
if(parameters.testpointName.length > 7) { throw "Test point name must be 7 characters or less." }
SystemOpenTestPoint.testpointName = parameters.testpointName;
sendCommand(SystemOpenTestPoint);
var usingNitrogen = (parameters.nitrogenIgnitionFlowRateN2Slpm>0)
