// delay to get to safed mode?
mSleep(2000);
// Turn on chamber lights for viewing igniter insertion
IlluminationConfigure.sideLEDBankState = 1;
IlluminationConfigure.endLEDBankState = 1;
sendCommand(IlluminationConfigure);
// Insert the fiber
if( SystemDefineSetup.efieldConfig == 0 )
{
print("Moving fiber to its starting position");
FiberMove.position = parameters.fiberIgnitionPosition;
FiberMove.velocity = 3000;
sendCommand(FiberMove);
}
// Insert the igniter
if( parameters.igniterIgnitionPosition != 0)
{
print("Inserting igniter");
IgniterMove.position = parameters.igniterIgnitionPosition;
sendCommand(IgniterMove);
}
