IgniterSetupMoveWithParameters.deceleration = 5000;
sendCommand(IgniterSetupMoveWithParameters);
// make sure ACME valves are closed before opening CIR manifolds
sendCommand(FlowCloseAll);
if ( parameters.useFoma && (usingNitrogen))
{
print("Opening CIR nitrogen manifold");
// This function in helpers.js waits until complete or throws an error.
// The parameters are (N2, O2, Diluent, Fuel, N2 Bypass, delayMs)
openManifolds(true, false, false, false, true, 6000);
cirManifoldsOpen = true;
}
var cirManifoldStartTime = new Date().getTime();
// priming N2 period 1
if ( (parameters.nitrogenIgnitionFlowRateN2Slpm > 0) &&
(parameters.nitrogenPriming1DurationSec > 0))
{
// open N2 valve and MFC and prime the nitrogen
FlowSetSolenoidValveState.solenoidValve = 7;
FlowSetSolenoidValveState.state = 1;
sendCommand(FlowSetSolenoidValveState);
mSleep(500);
