FlowSetMfcRate.massFlowController = 2;
FlowSetMfcRate.flowSlm = parameters.nitrogenIgnitionFlowRateN2Slpm;
sendCommand(FlowSetMfcRate);
// for TADS timestamp of MFCs open
print("Priming gas lines for");
print("Priming nitrogen (period 1) for " + parameters.nitrogenPriming1DurationSec + " sec");
var startTime = new Date().getTime();
while ( updateDurationRemaining(startTime, parameters.nitrogenPriming1DurationSec) > 0 )
{
mSleep(1000);
}
}
// Start pre-ignition data capture and wait the prescribed time.
print("Recording pre-ignition data for " + parameters.preIgnitionDataTimeSec + " sec");
sendCommand(DataRecordingStart);
var secsRemaining = parameters.preIgnitionDataTimeSec;
SystemTelemetry.scriptDurationRemaining = secsRemaining;
while ( secsRemaining > 0 )
{
mSleep(1000);
secsRemaining--;
SystemTelemetry.scriptDurationRemaining = secsRemaining;
}
// Start the IPSU(s) recording images
if ( parameters.useIPSUs == true)
{
print("Setting IPSU(s) pre-ignition archive rates");
// set the pre-ignition archive rate for IPSU1
IpsuSetArchiveRate.ipsu = 1;
IpsuSetArchiveRate.archiveRate = parameters.ipsu1PreIgnitionArchiveRate;
sendCommand(IpsuSetArchiveRate);
// need delay between identical commands so 2nd set of params not used in 1st command
mSleep(100);
// set the pre-ignition archive rate for IPSU2
IpsuSetArchiveRate.ipsu = 2;
IpsuSetArchiveRate.archiveRate = parameters.ipsu2PreIgnitionArchiveRate;
sendCommand(IpsuSetArchiveRate);
// This is a flag that gets set by the ImagingController if there is trouble
// talking to an IPSU
ImagingController.ipsuErrorFlag = false;
