sendStartIpsusCommand();
print("Starting IPSU(s) archiving. Waiting up to " + parameters.ipsuTimeoutSec + " sec");
var secsRemaining = parameters.ipsuTimeoutSec;
while ( secsRemaining > 0 )
{
SystemTelemetry.scriptDurationRemaining = secsRemaining;
if ( IpsuTelemetry.ipsuPhase == 5 ) { break; }
if ( ImagingController.ipsuErrorFlag == true ) { break; }
mSleep(1000);
secsRemaining--;
}
if ( ImagingController.ipsuErrorFlag == true ) { throw "IPSU error" };
if ( secsRemaining <= 0 ) { throw "IPSU timeout error" };
ipsusStarted = true;
print("Recording pre-ignition images for " + parameters.preIgnitionImageTimeSec + " sec");
secsRemaining = parameters.preIgnitionImageTimeSec;
SystemTelemetry.scriptDurationRemaining = secsRemaining;
while ( secsRemaining > 0 )
{
mSleep(1000);
secsRemaining--;
SystemTelemetry.scriptDurationRemaining = secsRemaining;
}
}
if ( parameters.useFoma && usingFuel)
{
// under certain conditions a delay is needed between CIR scripts
if ( cirManifoldsOpen == true && ( new Date().getTime() - cirManifoldStartTime < 6000 ))
{
print("Waiting 6 seconds between CIR manifold scripts");
// CIR open manifold script was run and 6 seconds have not yet elapsed
mSleep(6000);
}
print("Opening CIR fuel manifold");
openFuelManifold();
cirManifoldsOpen = true;
}
// Turn off the lights
IlluminationConfigure.sideLEDBankState = 0;
IlluminationConfigure.endLEDBankState = 0;
sendCommand(IlluminationConfigure);
