IntensifiedCameraGate.gateType = 1;
IntensifiedCameraGate.pulsedGateWidthCounts = 0;
sendCommand(IntensifiedCameraGate);
mSleep(500);
IntensifiedCameraGainAmplitude.gainAmplitudeCounts =
intensifierGainToRaw(parameters.intensifierGainAmplitude);
sendCommand(IntensifiedCameraGainAmplitude);
