AnalogCameraSetShutter.shutter = parameters.analogCameraIgnitionShutter;
sendCommand(AnalogCameraSetShutter);
// priming N2 period 2
if ( (parameters.nitrogenIgnitionFlowRateN2Slpm > 0) &&
