var timeStampMs = 0;
while ( timeStampMs <= maxTime )
{
if ( timeStampMs == fuelOpenValvesTimeMs)
{
// Start fuel flow (and N2 flow if not already priming)
print("Starting fuel flow at ignition flow rate");
// Open valves
FlowSetAllSolenoidValveStates.SVA1State = 0;
